input.script:
const data = {
  totalMath: document.querySelectorAll('.ltx_Math').length,
  inlineMath: document.querySelectorAll('.ltx_Math.ltx_MathInline, .ltx_mathinline').length,
  displayMath: document.querySelectorAll('.ltx_math, .ltx_equation, .ltx_equationgroup').length,
  numberedEquations: document.querySelectorAll('.ltx_equation').length,
  equationGroups: document.querySelectorAll('.ltx_equationgroup').length,
};
// Get all equation numbers (ids)
const eqs = Array.from(document.querySelectorAll('.ltx_equation, .ltx_equationgroup')).map(eq => ({
  id: eq.id,
  className: eq.className,
  text: eq.textContent.slice(0, 100)
}));
return {summary: data, equations: eqs};

// Get all equations including appendix
const allEqs = Array.from(document.querySelectorAll('.ltx_equation')).map(eq => ({
  id: eq.id,
  parentId: eq.closest('.ltx_equationgroup')?.id || eq.closest('section')?.id || 'unknown',
  text: eq.textContent.replace(/\s+/g, ' ').slice(0, 150)
}));
const allGroups = Array.from(document.querySelectorAll('.ltx_equationgroup')).map(g => ({
  id: g.id,
  parentId: g.closest('section')?.id || 'unknown',
  text: g.textContent.replace(/\s+/g, ' ').slice(0, 200)
}));
return {individualEquations: allEqs, equationGroups: allGroups};

// Get all sections and their equations
const sections = Array.from(document.querySelectorAll('section')).map(s => ({
  id: s.id,
  title: s.querySelector('h2, h3, h4')?.textContent || '',
  eqs: Array.from(s.querySelectorAll('.ltx_equationgroup, .ltx_equation')).map(eq => ({
    id: eq.id,
    text: eq.textContent.replace(/\s+/g, ' ').slice(0, 200)
  }))
})).filter(s => s.eqs.length > 0);
return sections;

// Look at appendix B specifically
const appB = document.querySelector('#A2') || Array.from(document.querySelectorAll('section')).find(s => s.id?.startsWith('A2') || s.textContent.includes('Alternative Similarity'));
if (appB) {
  const eqs = Array.from(appB.querySelectorAll('.ltx_equationgroup, .ltx_equation')).map(eq => ({
    id: eq.id,
    text: eq.textContent.replace(/\s+/g, ' ').slice(0, 250)
  }));
  return {found: true, id: appB.id, eqs};
}
// Search for any eq elements across the document
const all = Array.from(document.querySelectorAll('.ltx_equationgroup')).map(g => ({
  id: g.id,
  parent: g.closest('section')?.id
}));
return {found: false, allGroups: all};

// Get all sections with their IDs and titles for the entire paper
const sections = Array.from(document.querySelectorAll('section.ltx_section, section.ltx_appendix, section.ltx_subsection')).map(s => ({
  id: s.id,
  title: s.querySelector('h2, h3, h4')?.textContent || '',
  eqGroupCount: s.querySelectorAll('.ltx_equationgroup').length,
  inlineMathCount: s.querySelectorAll('.ltx_Math').length
}));
return sections;

// Get the full content of Appendix B
const appB = document.querySelector('#A2');
return {
  id: appB?.id,
  content: appB?.textContent.slice(0, 2000) || 'Not found'
};
